<script lang="ts">
import {SerialWrites} from './serial';
import {onMount,onDestroy,tick} from 'svelte';import {notificationAction} from './bridge';import {notificationError,pairingLinkHint,type PairTicket,type Recipient} from './notifications';import Icon from './Icon.svelte';import Field from './Field.svelte';
let {token,t,onclose,onadd}:{token:string;t:(key:string)=>string;onclose:()=>void;onadd:(recipient:Recipient)=>void}=$props();
const pairing=new SerialWrites();let dialog:HTMLDialogElement;let group=$state(false);let mode=$state('pair');let ticket=$state<PairTicket|null>(null);let found=$state<Recipient|null>(null);let chosen=$state(false);let name=$state('');let chat=$state('');let busy=$state(false);let error=$state('');let copied=$state(false);let generation=0;let alive=true;let timer:ReturnType<typeof setTimeout>|undefined;
function cancel(){generation++;clearTimeout(timer);const id=ticket?.id;ticket=null;if(id)void pairing.enqueue(()=>notificationAction({action:'cancel_pair',id})).catch(()=>{});}
async function poll(version:number,id:string){try{const result=await notificationAction<Recipient|null>({action:'poll_pair',id});if(!alive||generation!==version)return;if(result){found=result;chosen=true;name=result.label;return;}timer=setTimeout(()=>void poll(version,id),1500);}catch(reason){if(alive&&generation===version)error=notificationError(reason,t);}}
async function begin(){cancel();const version=generation;const selectedGroup=group;busy=true;error='';found=null;chosen=false;copied=false;try{await pairing.enqueue(async()=>{if(!alive||generation!==version)return;const value=await notificationAction<PairTicket>({action:'begin_pair',token,group:selectedGroup});if(!alive||generation!==version){await notificationAction({action:'cancel_pair',id:value.id});return;}ticket=value;void poll(version,value.id);});}catch(reason){if(alive&&generation===version)error=notificationError(reason,t);}finally{if(alive&&generation===version)busy=false;}}
function setMode(next:string){cancel();busy=false;mode=next;found=null;chosen=false;error='';if(next==='pair')void begin();else void tick().then(()=>dialog.querySelector<HTMLInputElement>('input')?.focus());}
async function link(action:'open_pair'|'copy_pair'){if(!ticket)return;try{await notificationAction({action,id:ticket.id});copied=action==='copy_pair';}catch(reason){error=notificationError(reason,t);}}
async function check(){const version=++generation;busy=true;error='';found=null;chosen=false;try{const recipient=await notificationAction<Recipient>({action:'chat',token,chat_id:chat.trim()});if(alive&&generation===version){found=recipient;name=recipient.label;chosen=true;}}catch(reason){if(alive&&generation===version)error=notificationError(reason,t);}finally{if(alive&&generation===version)busy=false;}}
onMount(()=>{dialog.showModal();void begin();});onDestroy(()=>{alive=false;cancel();dialog?.close();});
</script>
<dialog bind:this={dialog} class="profile-editor recipient-dialog" oncancel={event=>{event.preventDefault();onclose();}}><form onsubmit={event=>{event.preventDefault();if(found&&chosen)onadd({...found,label:name.trim()||found.label});}}><h1>{t('Добавить получателя')}</h1><div class="editor-scroll recipient-content">
{#if mode==='pair'}<div class="mode-buttons"><button type="button" class:selected={!group} onclick={()=>{if(group){group=false;void begin();}}}><Icon name="user"/>{t('Личный чат')}</button><button type="button" class:selected={group} onclick={()=>{if(!group){group=true;void begin();}}}><Icon name="office"/>{t('Группа')}</button></div>
<p class="muted">{t(group?'Добавить бота в группу по ссылке.':'Открыть бота в Telegram и нажать «Начать».')}</p>
{#if !found}<div class="recipient-link-actions"><button type="button" disabled={busy||!ticket} onclick={()=>void link('open_pair')}><Icon name="send"/>{t('Открыть бота')}</button><button type="button" disabled={busy||!ticket} onclick={()=>void link('copy_pair')}><Icon name={copied?'check':'copy'}/>{t(copied?'Скопировано':'Скопировать ссылку')}</button><button type="button" class="icon-button" disabled={busy} title={t('Повторить')} aria-label={t('Повторить')} onclick={()=>void begin()}><Icon name="restart"/></button></div><small class="muted">{pairingLinkHint(ticket?.expires_in_seconds,t)}</small>{/if}
{:else}<Field label={t('Chat ID или @канал')} icon="id" bind:value={chat}/><small class="muted">{t('Личный чат: сначала нажать «Начать» у бота. Для группы — добавить бота. Для канала — дать ему право публикации.')}</small><button type="button" class="recipient-check" disabled={busy||!chat.trim()} onclick={()=>void check()}><Icon name="check"/>{t('Проверить чат')}</button>{/if}
{#if found}<button type="button" class="found-recipient" class:chosen aria-pressed={chosen} onclick={()=>chosen=!chosen}><Icon name={found.type==='private'?'user':'office'}/><span><strong>{found.label}</strong><small>{found.username?'@'+found.username+' · ':''}{found.id}</small></span><Icon name={chosen?'check':'plus'}/></button><Field label={t('Название в приложении')} icon="user" bind:value={name}/>{/if}
<button type="button" class="disclosure" onclick={()=>setMode(mode==='pair'?'manual':'pair')}><Icon name={mode==='pair'?'pencil':'send'} size={16}/>{t(mode==='pair'?'Ввести Chat ID вручную':'Подключить по ссылке')}</button>
{#if error}<p class="notification-error" role="alert">{error}</p>{/if}</div><div class="editor-actions"><button type="button" onclick={onclose}>{t('Отмена')}</button><button type="submit" class="primary" disabled={!found||!chosen||busy}><Icon name="plus"/>{t('Добавить')}</button></div></form></dialog>
